create or replace function public.create_full_property_asset(p_administration_id uuid,p_property_type public.property_type,p_name text,p_city text,p_address text,p_country_code char(2) default 'CO',p_has_administration boolean default false,p_administration_fee numeric default null) returns public.rental_subjects language plpgsql security definer set search_path='' as $$ declare v_property public.properties; v_subject public.rental_subjects; begin if public.can_manage_administration(p_administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; if nullif(btrim(p_name),'') is null then raise exception 'PROPERTY_NAME_REQUIRED'; end if; if nullif(btrim(p_city),'') is null then raise exception 'CITY_REQUIRED'; end if; if nullif(btrim(p_address),'') is null then raise exception 'ADDRESS_REQUIRED'; end if; insert into public.properties(administration_id,property_type,rental_mode,name,country_code,city,address,has_administration,administration_fee) values(p_administration_id,p_property_type,'FULL_PROPERTY',btrim(p_name),p_country_code,btrim(p_city),btrim(p_address),p_has_administration,case when p_has_administration then p_administration_fee else null end) returning * into v_property; insert into public.rental_subjects(administration_id,subject_type,property_id) values(p_administration_id,'FULL_PROPERTY',v_property.id) returning * into v_subject; return v_subject; end $$;

create or replace function public.create_room_rental_property(p_administration_id uuid,p_property_type public.property_type,p_name text,p_city text,p_address text,p_country_code char(2) default 'CO',p_has_administration boolean default false,p_administration_fee numeric default null) returns public.properties language plpgsql security definer set search_path='' as $$ declare v_property public.properties; begin if public.can_manage_administration(p_administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; if nullif(btrim(p_name),'') is null then raise exception 'PROPERTY_NAME_REQUIRED'; end if; if nullif(btrim(p_city),'') is null then raise exception 'CITY_REQUIRED'; end if; if nullif(btrim(p_address),'') is null then raise exception 'ADDRESS_REQUIRED'; end if; insert into public.properties(administration_id,property_type,rental_mode,name,country_code,city,address,has_administration,administration_fee) values(p_administration_id,p_property_type,'BY_ROOMS',btrim(p_name),p_country_code,btrim(p_city),btrim(p_address),p_has_administration,case when p_has_administration then p_administration_fee else null end) returning * into v_property; return v_property; end $$;

create or replace function public.create_room_asset(p_property_id uuid,p_name text,p_bathroom_type public.bathroom_type default null,p_furnished boolean default false,p_description text default null) returns public.rental_subjects language plpgsql security definer set search_path='' as $$ declare v_property public.properties; v_room public.rooms; v_subject public.rental_subjects; begin select * into v_property from public.properties where id=p_property_id; if not found then raise exception 'PROPERTY_NOT_FOUND'; end if; if public.can_manage_administration(v_property.administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; if v_property.rental_mode<>'BY_ROOMS' then raise exception 'PROPERTY_NOT_BY_ROOMS'; end if; if nullif(btrim(p_name),'') is null then raise exception 'ROOM_NAME_REQUIRED'; end if; insert into public.rooms(administration_id,property_id,name,bathroom_type,furnished,description) values(v_property.administration_id,v_property.id,btrim(p_name),p_bathroom_type,p_furnished,nullif(btrim(p_description),'')) returning * into v_room; insert into public.rental_subjects(administration_id,subject_type,room_id) values(v_property.administration_id,'ROOM',v_room.id) returning * into v_subject; return v_subject; end $$;

create or replace function public.create_parking_asset(p_administration_id uuid,p_identifier text,p_property_id uuid default null,p_location text default null,p_covered boolean default null,p_allowed_vehicle_type public.vehicle_type default null,p_access_type text default null,p_observations text default null) returns public.rental_subjects language plpgsql security definer set search_path='' as $$ declare v_parking public.parkings; v_subject public.rental_subjects; begin if public.can_manage_administration(p_administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; if nullif(btrim(p_identifier),'') is null then raise exception 'PARKING_IDENTIFIER_REQUIRED'; end if; if p_property_id is not null and not exists(select 1 from public.properties p where p.id=p_property_id and p.administration_id=p_administration_id) then raise exception 'PROPERTY_ADMINISTRATION_MISMATCH'; end if; insert into public.parkings(administration_id,property_id,identifier,location,covered,allowed_vehicle_type,access_type,observations) values(p_administration_id,p_property_id,btrim(p_identifier),nullif(btrim(p_location),''),p_covered,p_allowed_vehicle_type,nullif(btrim(p_access_type),''),nullif(btrim(p_observations),'')) returning * into v_parking; insert into public.rental_subjects(administration_id,subject_type,parking_id) values(p_administration_id,'PARKING',v_parking.id) returning * into v_subject; return v_subject; end $$;

revoke all on function public.create_full_property_asset(uuid,public.property_type,text,text,text,char(2),boolean,numeric) from public,anon; grant execute on function public.create_full_property_asset(uuid,public.property_type,text,text,text,char(2),boolean,numeric) to authenticated,service_role;
revoke all on function public.create_room_rental_property(uuid,public.property_type,text,text,text,char(2),boolean,numeric) from public,anon; grant execute on function public.create_room_rental_property(uuid,public.property_type,text,text,text,char(2),boolean,numeric) to authenticated,service_role;
revoke all on function public.create_room_asset(uuid,text,public.bathroom_type,boolean,text) from public,anon; grant execute on function public.create_room_asset(uuid,text,public.bathroom_type,boolean,text) to authenticated,service_role;
revoke all on function public.create_parking_asset(uuid,text,uuid,text,boolean,public.vehicle_type,text,text) from public,anon; grant execute on function public.create_parking_asset(uuid,text,uuid,text,boolean,public.vehicle_type,text,text) to authenticated,service_role;